454:   /**
455:    * Goal mode only: if the run is nearing EITHER stop ceiling (maxTurns or
456:    * maxStopBlocks) and we haven't announced it yet, emit one approaching_limit
457:    * marker so the UI can offer a "再续" button while the run is still live.
458:    * Watches both limits because a re-blocked goal hits the stop-block cap long
459:    * before maxTurns. Idempotent within an approach window via approachAnnounced.
460:    */
461:   private maybeAnnounceApproachingLimit(): void {
462:     if (!this.config.goal || this.approachAnnounced) return;
463:     const cap = this.config.maxStopBlocks ?? GOAL_DEFAULT_MAX_STOP_BLOCKS;
464:     const prox = limitProximity(this.turnCount, this.config.maxTurns, this.stopBlockCount, cap);
465:     if (!prox.approaching) return;
466:     this.approachAnnounced = true;
467:     this.config.onStream?.({
468:       type: "goal_progress",
469:       goalId: this.config.goal.goalId,
470:       revision: this.config.goal.revision,
471:       status: "approaching_limit",
472:       round: this.stopBlockCount,
473:       turnsRemaining: prox.turnsRemaining,
474:       stopBlocksRemaining: prox.stopBlocksRemaining,
475:       nearest: prox.nearest,
476:     });
477:   }
